{
  "root_causes": [
    {
      "service": "ts-user-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, count(*) n, round(quantile_cont(duration::DOUBLE,0.5)/1e6,1) p50, round(quantile_cont(duration::DOUBLE,0.9)/1e6,1) p90, round(max(duration::DOUBLE)/1e6,1) mx FROM abnormal_traces WHERE service_name='ts-user-service' AND span_name='UserController.registerUser' UNION ALL SELECT 'nrm', count(*), round(quantile_cont(duration::DOUBLE,0.5)/1e6,1), round(quantile_cont(duration::DOUBLE,0.9)/1e6,1), round(max(duration::DOUBLE)/1e6,1) FROM normal_traces WHERE service_name='ts-user-service' AND span_name='UserController.registerUser'", "claim": "UserController.registerUser p90 rises from about 82 ms to about 294 ms (max 1567 ms) while its p50 stays near 81 ms."},
        {"kind": "trace", "sql": "SELECT s.span_name, count(*) n, round(quantile_cont(c.duration::DOUBLE,0.95)/1e6,1) caller_p95, round(quantile_cont(s.duration::DOUBLE,0.95)/1e6,1) callee_p95, round(quantile_cont(c.duration::DOUBLE-s.duration::DOUBLE,0.95)/1e6,1) gap_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-admin-user-service' AND c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.span_name='POST' GROUP BY 1", "claim": "Matched admin-user to user-service register calls show about 1 ms gap, so the extra time sits inside user-service."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration::DOUBLE,0.95)/1e6,1) p95 FROM abnormal_traces WHERE service_name='ts-user-service' AND span_name IN ('SELECT user.entity.User','INSERT ts.user','Transaction.commit','UserRepository.findByUserId') GROUP BY 1,2", "claim": "User-service database and repository spans stay at sub-millisecond to about 1.5 ms, so the database is not the slow part."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-user-service", "to": "ts-admin-user-service",
     "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(quantile_cont(c.duration::DOUBLE,0.95)/1e6,1) caller_p95, round(quantile_cont(s.duration::DOUBLE,0.95)/1e6,1) callee_p95 FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-admin-user-service' AND s.service_name='ts-user-service' AND c.span_name='POST' GROUP BY 1,2", "claim": "Admin-user POST calls to user-service take about 296 ms p95, mirroring the slow register span in user-service."}]},
    {"from": "ts-admin-user-service", "to": "ts-ui-dashboard",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, round(quantile_cont(duration::DOUBLE,0.95)/1e6,1) p95 FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2 UNION ALL SELECT service_name, span_name, count(*), round(quantile_cont(duration::DOUBLE,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2", "claim": "Dashboard POST /adminuserservice/users p95 rises from about 90 ms to about 721 ms, the user-visible symptom."}]}
  ]
}
